policy.reset_stage:
def reset_stage(self) -> None:
        if hasattr(self, "_executed_feedback"):
            self._executed_feedback.clear("stage_change")
        if hasattr(self, "_executed_progress"):
            self._executed_progress.clear("stage_change")
        self.reset_eds_chunk_memory("stage_change")
        self._stage_init_reward = None

policy.reset_eds_chunk_memory:
def reset_eds_chunk_memory(self, reason: str, *, warn: bool = False) -> None:
        self._eds_chunk_memory = None
        self._eds_chunk_memory_reset_reason = str(reason)
        if warn:
            log.warning(f"EDS chunk population memory reset: reason={reason}")

policy._observe_eds_score_call:
def _observe_eds_score_call(self, *, role, iter_idx, site):
        evidence = getattr(self, "_decision_evidence", None)
        if evidence is not None:
            evidence.set_scoring_scope(role=role, iter_idx=iter_idx, site=site)

policy._eds_score_population_as_cost:
def _eds_score_population_as_cost(
        self,
        samples: Tensor,
        *,
        keypoints: Optional[Tensor],
        guidance_fns: Optional[List[Callable]],
        reward_mode: str = "normal",
        shuffle_seed: int = 0,
        qd_quality_contract: ExecutedPrefixContract | FeedbackContract | None = None,
    ) -> tuple[Tensor, dict]:
        reward_mode = str(reward_mode or "normal")
        valid_modes = {"normal", "zero", "shuffled_keypoints", "inverted"}
        if reward_mode not in valid_modes:
            raise ValueError(f"Unsupported EDS reward_mode={reward_mode!r}")

        evidence = getattr(self, "_decision_evidence", None)
        if evidence is not None:
            evidence.begin_score_call()
        scoring_keypoints = keypoints
        if (
            reward_mode == "shuffled_keypoints"
            and keypoints is not None
            and keypoints.shape[0] > 1
        ):
            generator = torch.Generator(device=keypoints.device)
            generator.manual_seed(int(shuffle_seed))
            perm = torch.randperm(
                keypoints.shape[0],
                generator=generator,
                device=keypoints.device,
            )
            scoring_keypoints = keypoints.index_select(0, perm)

        projection_out = ({"capture_origin": True} if isinstance(qd_quality_contract, (FeedbackContract, ActuatorClippedContract))
                          else {} if qd_quality_contract is not None else None)
        if qd_quality_contract is not None:
            if reward_mode != "normal":
                raise RuntimeError("N2 canonical quality requires original normal reward mode")
            qd_quality_contract.validate(guidance_fns)
        rewards = self._score_particles(
            samples,
            scoring_keypoints,
            guidance_fns,
            slice_kind="eds",
            **({"projection_out": projection_out} if projection_out is not None else {}),
        )
        if reward_mode == "zero":
            rewards = torch.zeros_like(rewards)
        elif reward_mode == "inverted":
            rewards = -rewards
        quality_info = {}
        if qd_quality_contract is not None:
            qd_quality_contract.validate(guidance_fns)
            if not torch.isfinite(rewards).all():
                raise FloatingPointError("N2 original provider reward is nonfinite")
            quality_info["raw_rewards"] = rewards.detach().clone()
            quality_info["qd_scored_actions"] = samples.detach().clone()
            if isinstance(qd_quality_contract, ActuatorClippedContract):
                rewards, clipped_mask = qd_quality_contract.score(
                    samples[:, :8, RDT_GUIDED_TRANSLATION_INDICES], projection_out["source_origins"],
                    projection_out["projected_xyz"], scoring_keypoints, rewards)
                quality_info["clipped_prefix_mask"] = clipped_mask
            elif isinstance(qd_quality_contract, LiftAfterCloseContract):
                decoded = self._decode_visualization_action_candidates(samples)
                bonus_function = (close_hold_then_lift_bonus
                                  if qd_quality_contract.mode == HOLD_LIFT_MODE
                                  else close_then_lift_bonus)
                bonus = bonus_function(
                    projection_out["projected_xyz"], scoring_keypoints, decoded,
                    target_index=qd_quality_contract.target_index,
                ).to(device=rewards.device, dtype=rewards.dtype)
                quality_info["lift_bonus"] = bonus.detach().clone()
                if bool((bonus != 0).any().item()):
                    rewards = rewards + bonus
            elif isinstance(qd_quality_contract, FeedbackContract):
                qd_quality_contract.record(samples, projection_out["projected_xyz"],
                                           projection_out["source_origins"], rewards)
                if qd_quality_contract.active:
                    quality_started = time.perf_counter()
                    rewards = executed_feedback_quality(projection_out["projected_xyz"], scoring_keypoints,
                        target_index=qd_quality_contract.target_index, residual_previous=qd_quality_contract.residual)
                    qd_quality_contract.overhead_seconds += time.perf_counter() - quality_started
                # No eligible history: retain the exact already-computed raw tensor.
            else:
                rewards = executed_prefix_quality(projection_out["projected_xyz"], scoring_keypoints,
                                                  target_index=qd_quality_contract.target_index)
            if rewards.shape != quality_info["raw_rewards"].shape or rewards.dtype != samples.dtype:
                raise RuntimeError("N2 canonical quality/raw association mismatch")
        costs = -rewards
        evidence = getattr(self, "_decision_evidence", None)
        if evidence is not None:
            evidence.record("effective_quality", scoring_batch_id=evidence.scoring_batch_id,
                            reward_mode=reward_mode, quality=rewards, costs=costs,
                            **({"quality_mode": getattr(qd_quality_contract, "mode", "executed_prefix_v1"),
                                "raw_provider_quality": quality_info["raw_rewards"],
                                "target_index": qd_quality_contract.target_index,
                                "provider_identity": qd_quality_contract.identity,
                                **({"actuator_metadata": qd_quality_contract.metadata,
                                    "clipped_prefix_mask": quality_info["clipped_prefix_mask"]}
                                   if isinstance(qd_quality_contract, ActuatorClippedContract) else {}),
                                **({"lift_bonus": quality_info["lift_bonus"]}
                                   if isinstance(qd_quality_contract, LiftAfterCloseContract) else {})}
                               if qd_quality_contract is not None else {}))
        return costs.detach(), {"rewards": rewards.detach(), **quality_info}

