            ),
            qd_metrics_observer=_parse_eds_bool(
                cfg.get("qd_metrics_observer", False), "qd_metrics_observer"
            ),
        )
        if resolved.population_size <= 0:
            raise ValueError("EDS population_size must be positive")
        if resolved.cem_iters <= 0:
            raise ValueError("EDS cem_iters must be positive")
        if not math.isfinite(resolved.temperature) or resolved.temperature <= 0:
            raise ValueError("EDS temperature must be finite and positive")
        if resolved.renoise_t_max <= 0 or resolved.renoise_t_min <= 0:
            raise ValueError("EDS renoise_t_max and renoise_t_min must be positive")
        if resolved.renoise_t_min > resolved.renoise_t_max:
            raise ValueError("EDS renoise_t_min must be <= renoise_t_max")
        if resolved.reward_mode not in {"normal", "zero", "shuffled_keypoints", "inverted"}:
            raise ValueError(
                "EDS reward_mode must be one of normal, zero, shuffled_keypoints, inverted"
            )
        if resolved.initial_sampling_mode not in {"iid", "rbf_diverse_denoise"}:
            raise ValueError(
                "EDS initial_sampling_mode must be one of iid, rbf_diverse_denoise"
            )
        if not math.isfinite(resolved.initial_diversity_scale):
            raise ValueError("EDS initial_diversity_scale must be finite")
        if resolved.initial_diversity_start_ratio is not None:
            ratio = float(resolved.initial_diversity_start_ratio)
            if not math.isfinite(ratio) or ratio < 0.0 or ratio > 1.0:
                raise ValueError(
                    "EDS initial_diversity_start_ratio must be None or a finite value in [0, 1]"
                )
        if resolved.initial_diversity_fallback != "iid":
            raise ValueError("EDS initial_diversity_fallback MVP only supports iid")
        if resolved.truncated_rollout_mode not in EDS_TRUNCATED_ROLLOUT_MODES:
            raise ValueError(
                "EDS truncated_rollout_mode must be one of baseline, rbf_diverse"
            )
        if not math.isfinite(resolved.rollout_diversity_scale):
            raise ValueError("EDS rollout_diversity_scale must be finite")
        rollout_ratio = float(resolved.rollout_diversity_start_ratio)
        if not math.isfinite(rollout_ratio) or rollout_ratio < 0.0 or rollout_ratio > 1.0:
            raise ValueError(
                "EDS rollout_diversity_start_ratio must be a finite value in [0, 1]"
            )
        if resolved.rollout_diversity_skip_final_steps < 0:
            raise ValueError("EDS rollout_diversity_skip_final_steps must be >= 0")
        if resolved.parent_weighting_mode not in {
            "legacy_temperature",
            "adaptive_ess",
        }:
            raise ValueError(
                "EDS parent_weighting_mode must be one of legacy_temperature, adaptive_ess"
            )
        if resolved.parent_coverage_mode not in {"none", "eef_kcenter"}:
            raise ValueError(
                "EDS parent_coverage_mode must be one of none, eef_kcenter"
            )
        if resolved.rollout_diversity_control_mode not in {
            "fixed",
            "adaptive_band",
        }:
            raise ValueError(
                "EDS rollout_diversity_control_mode must be one of fixed, adaptive_band"
            )
        if resolved.chunk_population_mode not in {"fresh", "warm_start_mix"}:
            raise ValueError(
                "EDS chunk_population_mode must be one of fresh, warm_start_mix"
            )
        if resolved.search_schedule_mode not in {"legacy_linear", "adaptive"}:
            raise ValueError(
                "EDS search_schedule_mode must be one of legacy_linear, adaptive"
            )
        if (
            not math.isfinite(resolved.selection_ess_target_ratio)
            or resolved.selection_ess_target_ratio <= 0.0
            or resolved.selection_ess_target_ratio > 1.0
        ):
            raise ValueError("EDS selection_ess_target_ratio must be in (0, 1]")
        if (
            not math.isfinite(resolved.selection_beta_max)
            or resolved.selection_beta_max <= 0.0
        ):
            raise ValueError("EDS selection_beta_max must be finite and positive")
        if resolved.selection_bisection_steps <= 0:
            raise ValueError("EDS selection_bisection_steps must be positive")
        if resolved.parent_anchor_count < 0:
            raise ValueError("EDS parent_anchor_count must be >= 0")
        if (
            not math.isfinite(resolved.parent_anchor_reward_quantile)
            or resolved.parent_anchor_reward_quantile < 0.0
            or resolved.parent_anchor_reward_quantile > 1.0
        ):
            raise ValueError("EDS parent_anchor_reward_quantile must be in [0, 1]")
        if resolved.elite_carryover_count < 0:
            raise ValueError("EDS elite_carryover_count must be >= 0")
        if resolved.elite_carryover_count >= resolved.population_size:
            raise ValueError(
                "EDS elite_carryover_count must be less than population_size"
            )
        if (
            resolved.elite_carryover_count + resolved.parent_anchor_count
            > resolved.population_size
        ):
            raise ValueError(
                "EDS elite_carryover_count + parent_anchor_count must be <= population_size"
            )
        if (
            not math.isfinite(resolved.rollout_diversity_target_ratio)
            or resolved.rollout_diversity_target_ratio < 0.0
        ):
            raise ValueError(
                "EDS rollout_diversity_target_ratio must be finite and >= 0"
            )
        if (
            not math.isfinite(resolved.rollout_diversity_band_ratio)
            or resolved.rollout_diversity_band_ratio < 0.0
        ):
            raise ValueError(
                "EDS rollout_diversity_band_ratio must be finite and >= 0"
            )
        if (
            not math.isfinite(resolved.rollout_diversity_scale_min)
            or resolved.rollout_diversity_scale_min < 0.0
        ):
            raise ValueError(
                "EDS rollout_diversity_scale_min must be finite and nonnegative"
            )
        if (
            not math.isfinite(resolved.rollout_diversity_scale_max)
            or resolved.rollout_diversity_scale_max < 0.0
        ):
            raise ValueError(
                "EDS rollout_diversity_scale_max must be finite and nonnegative"
            )
        if resolved.rollout_diversity_scale_min > resolved.rollout_diversity_scale_max:
            raise ValueError(
                "EDS rollout_diversity_scale_min must be <= rollout_diversity_scale_max"
            )
        if (
            not math.isfinite(resolved.rollout_diversity_decay_floor)
            or resolved.rollout_diversity_decay_floor < 0.0
            or resolved.rollout_diversity_decay_floor > 1.0
        ):
            raise ValueError("EDS rollout_diversity_decay_floor must be in [0, 1]")
        if (
            not math.isfinite(resolved.chunk_memory_fraction)
            or resolved.chunk_memory_fraction < 0.0
            or resolved.chunk_memory_fraction >= 1.0
        ):
            raise ValueError("EDS chunk_memory_fraction must be in [0, 1)")
        if resolved.chunk_memory_renoise_steps <= 0:
            raise ValueError("EDS chunk_memory_renoise_steps must be positive")
        if (
            not math.isfinite(resolved.chunk_memory_reward_guard_quantile)
            or resolved.chunk_memory_reward_guard_quantile < 0.0
            or resolved.chunk_memory_reward_guard_quantile > 1.0
        ):
            raise ValueError(
                "EDS chunk_memory_reward_guard_quantile must be in [0, 1]"
            )
        if not 1 <= resolved.adaptive_min_cem_iters <= resolved.cem_iters:
            raise ValueError(
                "EDS adaptive_min_cem_iters must be in [1, cem_iters]"
            )
        if resolved.adaptive_early_stop_patience <= 0:
            raise ValueError("EDS adaptive_early_stop_patience must be positive")
        if (
            not math.isfinite(resolved.adaptive_reward_improvement_eps)
            or resolved.adaptive_reward_improvement_eps < 0.0
        ):
            raise ValueError(
                "EDS adaptive_reward_improvement_eps must be finite and >= 0"
            )
        if resolved.use_cem and resolved.num_elites > resolved.population_size:
            raise ValueError(
                "EDS num_elites must be <= population_size when use_cem=true"
            )
        if resolved.use_cem and resolved.num_elites <= 0:
            raise ValueError("EDS num_elites must be positive when use_cem=true")
        for field_name in (
            "initial_diversity_descriptor_mode",
            "rollout_diversity_descriptor_mode",
        ):
            if getattr(resolved, field_name) not in EDS_DIVERSITY_DESCRIPTOR_MODES:
                raise ValueError(
                    f"{field_name} must be one of {sorted(EDS_DIVERSITY_DESCRIPTOR_MODES)}"
                )
        _validate_direction_rbf_config(resolved.__dict__)
        if resolved.qd_archive_mode not in {"none", "grid_archive"}:
            raise ValueError("EDS qd_archive_mode must be one of none, grid_archive")
        if resolved.qd_final_selection_mode not in {DEFAULT_FINAL_SELECTION_MODE, TERMINAL_POPULATION_MODE, GRASP_TIMING_MODE, CONTACT_SWEEP_MODE}:
            raise ValueError("EDS qd_final_selection_mode is unsupported")
        if resolved.qd_final_selection_mode in {TERMINAL_POPULATION_MODE, GRASP_TIMING_MODE, CONTACT_SWEEP_MODE}:
            terminal_lift_quality = (resolved.qd_quality_mode in {*LIFT_MODES, ACTUATOR_CLIPPED_MODE}
                                     and resolved.qd_final_selection_mode == GRASP_TIMING_MODE
                                     and resolved.qd_descriptor == DIRECTION_HEIGHT_DESCRIPTOR)
            required_terminal = {
                "qd_quality_mode": resolved.qd_quality_mode if terminal_lift_quality else "provider",
                "reward_mode": "normal",
                "qd_archive_mode": "grid_archive",
                "qd_descriptor": (resolved.qd_descriptor
                                  if resolved.qd_final_selection_mode in {GRASP_TIMING_MODE, CONTACT_SWEEP_MODE}
                                  and resolved.qd_descriptor in {HEIGHT_AWARE_DESCRIPTOR, DIRECTION_HEIGHT_DESCRIPTOR}
                                  else "target_relative_endpoint_xy"),
                "qd_grid_shape": (4, 4), "qd_cell_capacity": 1, "qd_parent_sampling": "sparse_priority",
                "qd_bounds_update_policy": "fixed_initial", "qd_bounds_quantiles": (0.05, 0.95),
                "qd_bounds_expand_fraction": 0.1, "qd_min_axis_span_m": 0.08,
                "qd_global_quality_anchor_count": 0, "qd_secondary_lane_mode": "none",
                "qd_degenerate_fallback_policy": "none",
                "save_ed_cache": False, "use_initial_cache": False,
            }
            for name, expected in required_terminal.items():
                if getattr(resolved, name) != expected:
                    raise ValueError(f"N4 terminal population requires {name}={expected!r}")
        if (resolved.qd_descriptor in {HEIGHT_AWARE_DESCRIPTOR, DIRECTION_HEIGHT_DESCRIPTOR}
                and resolved.qd_final_selection_mode not in {GRASP_TIMING_MODE, CONTACT_SWEEP_MODE}):
            raise ValueError("Height or direction-height QD requires a grasp-aware terminal selector")
        if (resolved.qd_final_selection_mode == CONTACT_SWEEP_MODE
                and resolved.qd_descriptor != DIRECTION_HEIGHT_DESCRIPTOR):
            raise ValueError("N9 contact sweep requires the frozen N7 direction-height descriptor")
        if resolved.qd_quality_mode not in {"provider", "executed_prefix_v1", FEEDBACK_MODE, ACTUATOR_CLIPPED_MODE, *LIFT_MODES}:
            raise ValueError("EDS qd_quality_mode is unsupported")
        if resolved.qd_quality_mode in {"executed_prefix_v1", FEEDBACK_MODE}:
            required_quality = {
                "reward_mode": "normal", "qd_descriptor": "target_relative_endpoint_xy",
                "qd_grid_shape": (4, 4), "qd_cell_capacity": 1,
                "qd_bounds_update_policy": "fixed_initial", "qd_global_quality_anchor_count": 0,
                "qd_secondary_lane_mode": "none", "qd_degenerate_fallback_policy": "none",
                "population_size": 16, "cem_iters": 10, "use_cem": False,
                "elite_carryover_count": 0, "chunk_population_mode": "fresh",
                "chunk_memory_fraction": 0.0, "search_schedule_mode": "legacy_linear",
            }
            if resolved.qd_archive_mode == "grid_archive":
                required_quality.update({"qd_parent_sampling": "sparse_priority",
                    "qd_bounds_quantiles": (0.05, 0.95), "qd_bounds_expand_fraction": 0.1,
                    "qd_min_axis_span_m": 0.08})
            for name, expected in required_quality.items():
                if getattr(resolved, name) != expected:
                    raise ValueError(f"Executed-prefix quality requires {name}={expected!r}")
        if resolved.qd_quality_mode in {*LIFT_MODES, ACTUATOR_CLIPPED_MODE}:
            required_lift = {
                "reward_mode": "normal", "qd_archive_mode": "grid_archive",
                "qd_descriptor": DIRECTION_HEIGHT_DESCRIPTOR,
                "qd_final_selection_mode": GRASP_TIMING_MODE,
                "qd_grid_shape": (4, 4), "qd_cell_capacity": 1,
                "qd_parent_sampling": "sparse_priority",
                "qd_bounds_update_policy": "fixed_initial",
                "qd_global_quality_anchor_count": 0,
                "qd_secondary_lane_mode": "none",
                "qd_degenerate_fallback_policy": "none",
                "population_size": 16, "cem_iters": 10, "use_cem": False,
                "elite_carryover_count": 0, "chunk_population_mode": "fresh",
                "chunk_memory_fraction": 0.0, "search_schedule_mode": "legacy_linear",
            }
            for name, expected in required_lift.items():
                if getattr(resolved, name) != expected:
                    raise ValueError(f"N18 lift quality requires {name}={expected!r}")
        if resolved.qd_gripper_rescue_mode not in {"none", GRIPPER_RESCUE_MODE}:
            raise ValueError("Unsupported QD gripper rescue mode")
        if resolved.qd_gripper_rescue_mode == GRIPPER_RESCUE_MODE:
            required_rescue = {"qd_quality_mode": ACTUATOR_CLIPPED_MODE,
                "qd_parent_survivor_count": 0, "qd_sparse_exponent": 1.0,
                "qd_metrics_observer": True, "qd_tie_break": "stable_fingerprint",
                "qd_overflow_policy": "clamp_edge"}
            for field_name, expected in required_rescue.items():
                if getattr(resolved, field_name) != expected:
                    raise ValueError(f"N24 parent rescue requires {field_name}={expected!r}")
        if resolved.qd_degenerate_fallback_policy not in {"none", "control_v1"}:
            raise ValueError(
                "EDS qd_degenerate_fallback_policy must be none or control_v1"
            )
        if resolved.qd_descriptor not in {"target_relative_endpoint_xy", EXECUTION_INTENT_DESCRIPTOR,
                                          HEIGHT_AWARE_DESCRIPTOR, DIRECTION_HEIGHT_DESCRIPTOR}:
            raise ValueError(
                "EDS qd_descriptor must be a supported frozen XY, execution-intent, height-aware or direction-height mode"
            )
        if resolved.qd_descriptor == EXECUTION_INTENT_DESCRIPTOR:
            required_intent = {
                "qd_archive_mode": "grid_archive", "qd_grid_shape": (4, 4),
                "qd_cell_capacity": 1, "qd_parent_sampling": "sparse_priority",
                "qd_bounds_quantiles": (0.05, 0.95), "qd_bounds_expand_fraction": 0.1,
                "qd_min_axis_span_m": 0.08, "qd_bounds_update_policy": "fixed_initial",
                "qd_global_quality_anchor_count": 0, "qd_secondary_lane_mode": "none",
                "qd_degenerate_fallback_policy": "none",
            }
            for name, expected in required_intent.items():
                if getattr(resolved, name) != expected:
                    raise ValueError(f"Execution-intent QD requires {name}={expected!r}")
        if resolved.qd_grid_shape not in {(3, 3), (4, 4), (5, 5)}:
            raise ValueError("EDS qd_grid_shape is not a preregistered square grid")
        if resolved.qd_cell_capacity != 1:
            raise ValueError("EDS qd_cell_capacity must be 1")
        if resolved.qd_parent_survivor_count not in {0, 4}:
            raise ValueError("EDS qd_parent_survivor_count must be 0 or 4")
        if resolved.qd_parent_survivor_count == 4:
            required_survival = {
                "qd_archive_mode": "grid_archive",
                "qd_quality_mode": "provider",
                "qd_descriptor": DIRECTION_HEIGHT_DESCRIPTOR,
                "qd_final_selection_mode": GRASP_TIMING_MODE,
                "qd_parent_sampling": "sparse_priority",
                "qd_global_quality_anchor_count": 0,
                "qd_secondary_lane_mode": "none",
                "qd_bounds_update_policy": "fixed_initial",
                "elite_carryover_count": 0,
            }
            for field_name, expected in required_survival.items():
                if getattr(resolved, field_name) != expected:
                    raise ValueError(
                        f"N11 parent survival requires {field_name}={expected!r}"
                    )
        if resolved.qd_secondary_lane_mode not in {
            "none",
            "protected_reward_v1",
        }:
            raise ValueError(
                "EDS qd_secondary_lane_mode must be none or protected_reward_v1"
            )
        if resolved.qd_parent_sampling not in {
            "uniform_cells",
            "sparse_priority",
        }:
            raise ValueError(
                "EDS qd_parent_sampling must be uniform_cells or sparse_priority"
            )
        if resolved.qd_global_quality_anchor_count not in {0, 1}:
            raise ValueError(
                "EDS qd_global_quality_anchor_count must be 0 or 1"
            )
        if resolved.qd_global_quality_anchor_count == 1 and (
            resolved.qd_archive_mode != "grid_archive"
            or resolved.qd_parent_sampling != "sparse_priority"
            or resolved.qd_bounds_update_policy != "causal_envelope_v1"
            or resolved.qd_degenerate_fallback_policy != "none"
        ):
            raise ValueError(
                "EDS qd_global_quality_anchor_count=1 requires grid_archive, "
                "sparse_priority, causal_envelope_v1, and fallback none"
            )
        if resolved.qd_secondary_lane_mode == "protected_reward_v1" and (
            resolved.qd_archive_mode != "grid_archive"
            or resolved.qd_cell_capacity != 1
            or resolved.qd_parent_sampling != "sparse_priority"
            or resolved.qd_global_quality_anchor_count != 1
            or resolved.qd_bounds_update_policy != "causal_envelope_v1"
            or resolved.qd_degenerate_fallback_policy != "none"
        ):
            raise ValueError(
                "EDS qd_secondary_lane_mode=protected_reward_v1 requires "
                "grid_archive, capacity 1, sparse_priority, global quality "
                "anchor 1, causal_envelope_v1, and fallback none"
            )
        if resolved.qd_sparse_exponent != 1.0:
            raise ValueError("EDS qd_sparse_exponent must be 1.0")
        if resolved.qd_bounds_quantiles not in {
            (0.0, 1.0),
            (0.05, 0.95),
            (0.10, 0.90),
        }:
            raise ValueError("EDS qd_bounds_quantiles are not preregistered")
        if resolved.qd_bounds_expand_fraction not in {0.0, 0.10, 0.20}:
            raise ValueError(
                "EDS qd_bounds_expand_fraction is not preregistered"
            )
        if resolved.qd_min_axis_span_m not in {0.04, 0.08, 0.12}:
            raise ValueError("EDS qd_min_axis_span_m is not preregistered")
        if resolved.qd_bounds_update_policy not in {
            "fixed_initial",
            "causal_envelope_v1",
        }:
            raise ValueError(
                "EDS qd_bounds_update_policy must be fixed_initial or "
                "causal_envelope_v1"
            )
        if resolved.qd_overflow_policy != "clamp_edge":
            raise ValueError("EDS qd_overflow_policy must be clamp_edge")
        if resolved.qd_tie_break != "stable_fingerprint":
            raise ValueError("EDS qd_tie_break must be stable_fingerprint")

        validate_source_option(resolved)
        if resolved.diversity_update_mode == TRUST_RBF_UPDATE:
            validate_trust_option(resolved)
        else:
            validate_update_option(resolved)
            validate_placement(resolved)
        clipped_rbf = CLIPPED_RBF_MODE in {
            resolved.initial_diversity_descriptor_mode, resolved.rollout_diversity_descriptor_mode}
        if clipped_rbf:
            n25_required = {
                "initial_diversity_descriptor_mode": CLIPPED_RBF_MODE,
                "rollout_diversity_descriptor_mode": CLIPPED_RBF_MODE,
                "qd_archive_mode": "grid_archive", "qd_quality_mode": ACTUATOR_CLIPPED_MODE,
                "qd_descriptor": DIRECTION_HEIGHT_DESCRIPTOR,
                "qd_final_selection_mode": GRASP_TIMING_MODE,
                "qd_gripper_rescue_mode": "none", "qd_parent_survivor_count": 0,
            }
            for field_name, expected in n25_required.items():
                if getattr(resolved, field_name) != expected:
                    raise ValueError(f"N25 requires {field_name}={expected!r}")
        if resolved.qd_archive_mode == "grid_archive":
            required = {
                "population_size": 16,
                "cem_iters": 10,
                "use_cem": False,
                "renoise_t_max": 3,
                "renoise_t_min": 1,
                "initial_sampling_mode": "rbf_diverse_denoise",
                "initial_diversity_descriptor_mode": CLIPPED_RBF_MODE if clipped_rbf else "absolute_eef",
                "initial_diversity_scale": 20.0,
                "initial_diversity_start_ratio": 0.8,
                "truncated_rollout_mode": "rbf_diverse",
                "rollout_diversity_descriptor_mode": CLIPPED_RBF_MODE if clipped_rbf else "absolute_eef",
                "rollout_diversity_scale": 20.0,
                "rollout_diversity_start_ratio": 0.6,
                "rollout_diversity_iters": "all",
                "rollout_diversity_skip_final_steps": 0,
                "parent_weighting_mode": "legacy_temperature",
                "parent_coverage_mode": "none",
                "parent_anchor_count": 0,
                "elite_carryover_count": 0,
                "chunk_population_mode": "fresh",
                "chunk_memory_fraction": 0.0,
                "rollout_diversity_control_mode": "fixed",
                "search_schedule_mode": "legacy_linear",
            }
            for field_name, expected in required.items():
                if getattr(resolved, field_name) != expected:
                    raise ValueError(
                        "EDS grid_archive requires "
                        f"{field_name}={expected!r}"
                    )
        validate_progress_config(resolved, self._action_chunk_horizon)
        return resolved
